const {x, y} = IO.loadSpiralData();
const points = x.map(point => point.toArray());
const n = points.length;
const labels = NMath.vec.fromArray(y);
let sigma = 0.18;
let lambda = 0.05;

const fit = (sigma, lambda) => {
    const gaussianKernel = (a, b) => {
        const dx = a[0] - b[0];
        const dy = a[1] - b[1];
        return Math.exp(-(dx * dx + dy * dy) / (2 * sigma * sigma));
    };
    const kernelMatrix = NMath.mat(points.flatMap((point, i) =>
        points.map((other, j) => gaussianKernel(point, other) + (i === j ? lambda : 0))
    ), [n, n]);
    const alpha = kernelMatrix.solve(labels, {maxIterations: 12000, tolerance: 1e-4});
    const residual = kernelMatrix.prodVec(alpha).sub(labels).length();
    if (!Number.isFinite(residual) || residual > 1e-3) {
        throw new Error(`Kernel ridge solver did not converge (residual: ${residual})`);
    }
    const predict = point => {
        let prediction = 0;
        for (let i = 0; i < n; i++) {
            prediction += alpha.components[i] * gaussianKernel(points[i], point);
        }
        return prediction;
    };
    const correct = points.reduce((count, point, i) => count + (predict(point) * y[i] > 0 ? 1 : 0), 0);
    console.log(`Training accuracy: ${(100 * correct / n).toFixed(1)}%, residual: ${residual.toExponential(2)}`);
    return predict;
};

let predict = fit(sigma, lambda);
const plot = IO.plotPointCloud(x, {
    aspect: "equal",
    radius: 0.022,
    color: y.map(label => label === 1 ? [1, 0, 0] : [0, 0, 1]),
    backgroundSampleSize: 4,
    background: point => {
        const prediction = predict(point);
        const strength = 0.3 * Math.min(1, Math.abs(prediction));
        const base = 0.04;
        return prediction >= 0 ? [base + strength, base, base] : [base, base, base + strength];
    },
});

let updateTimer;
const update = () => {
    clearTimeout(updateTimer);
    updateTimer = setTimeout(() => {
        predict = fit(sigma, lambda);
        plot.render();
    }, 150);
};
const ui = IO.UI(
    {type: "canvas", value: () => plot},
    {type: "slider", value: () => ({
        title: "Sigma:", min: 0.05, max: 0.5, step: 0.01, value: sigma,
        onChange: value => { sigma = value; update(); },
    })},
    {type: "slider", value: () => ({
        title: "Lambda:", min: 0.05, max: 0.5, step: 0.01, value: lambda,
        onChange: value => { lambda = value; update(); },
    })},
);
ui;
